const $=id=>document.getElementById(id);
const MESSAGE_LANGS=["ko","ja","en","zh-CN","zh-TW"];
function selectedLanguage(id){const v=$(id).value;return MESSAGE_LANGS.includes(v)?v:"auto"}
function messageLanguage(result,fallback){return MESSAGE_LANGS.includes(result?.replyLanguage)?result.replyLanguage:fallback}
// Model-written text keeps the language it was generated in, so line breaking
// and fonts stay correct even if the page language changes afterwards.
function markLang(ids,lang){for(const id of ids){const el=document.getElementById(id);if(el&&lang)el.lang=lang}}
const LANGUAGE_NAMES={"ko":"한국어","ja":"日本語","en":"English","zh-CN":"简体中文","zh-TW":"繁體中文"};
function renderMeaning(id,data,draft){
 const meaning=data?.replyMeaning;
 $(id+"Box").hidden=!draft||typeof meaning!=="string"||!meaning.trim();
 $(id).textContent=typeof meaning==="string"?meaning.slice(0,700):"";
 // Name the reply's language only when it differs from the page language.
 const badge=document.getElementById(id+"Lang"),lang=MESSAGE_LANGS.includes(data?.replyLanguage)?data.replyLanguage:"";
 if(badge){badge.hidden=!draft||!lang||lang===locale;badge.textContent=lang?LANGUAGE_NAMES[lang]:"";if(lang)badge.lang=lang;else badge.removeAttribute("lang")}
}

